import csv,pathlib,collections
rows=[]
def path(item,side,suffix):
 root=pathlib.Path(item)/side
 matches=[p for p in root.rglob('*') if p.is_file() and str(p).endswith(suffix)]
 assert len(matches)==1,(item,side,suffix,matches)
 return str(matches[0])
def add(n,kind,spec,conf,impl,contract,reason):
 item=f'U{n:02d}'
 def loc(side,entries,sep):
  return ';'.join(path(item,side,suffix)+sep+str(line) for suffix,line in entries)
 assert len(reason.split())<=40,(item,len(reason.split()))
 rows.append(dict(item_id=item,divergence_kind=kind,contract_specificity=spec,confidence=conf,impl_locators=loc('impl',impl,':'),contract_locators=loc('contract',contract,'#'),rationale=reason))
